import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    df_counted = df[df['row_kind'] == 'counted'].copy()

    loss_ratio_by_line = (
        df_counted.groupby('line')
        .agg(total_incurred=('claim_amount', 'sum'), total_premium=('earned_premium', 'sum'))
        .reset_index()
    )
    loss_ratio_by_line['loss_ratio'] = loss_ratio_by_line['total_incurred'] / loss_ratio_by_line['total_premium']

    lr_results = [
        {"name": str(row['line']), "value": round(float(row['loss_ratio']), 6)}
        for _, row in loss_ratio_by_line.iterrows()
    ]

    result['segments'].append({
        "segment_column": "line",
        "metric_column": "claim_amount",
        "aggregation": "ratio",
        "label": "loss_ratio",
        "results": lr_results
    })

    claim_by_line = (
        df_counted.groupby('line')['claim_amount'].sum().reset_index()
    )
    claim_by_line = claim_by_line.nlargest(10, 'claim_amount')
    result['segments'].append({
        "segment_column": "line",
        "metric_column": "claim_amount",
        "aggregation": "sum",
        "label": None,
        "results": [{"name": str(r['line']), "value": float(r['claim_amount'])} for _, r in claim_by_line.iterrows()]
    })

    prem_by_line = (
        df_counted.groupby('line')['earned_premium'].sum().reset_index()
    )
    prem_by_line = prem_by_line.nlargest(10, 'earned_premium')
    result['segments'].append({
        "segment_column": "line",
        "metric_column": "earned_premium",
        "aggregation": "sum",
        "label": None,
        "results": [{"name": str(r['line']), "value": float(r['earned_premium'])} for _, r in prem_by_line.iterrows()]
    })

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

result['assumptions'].append("Loss ratio = sum(claim_amount) / sum(earned_premium) per line, counted rows only.")
result['assumptions'].append("Rows filtered to row_kind == 'counted' before all aggregations.")
result['assumptions'].append("Loss ratio values are fractions (e.g. 0.62 = 62%).")

