import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    region_claim = df.groupby('region')['claim_amount'].sum().reset_index()
    region_claim = region_claim.sort_values('claim_amount', ascending=False)
    result['segments'].append({
        "segment_column": "region",
        "metric_column": "claim_amount",
        "aggregation": "sum",
        "label": None,
        "results": [{"name": str(row['region']), "value": float(row['claim_amount'])} for _, row in region_claim.iterrows()]
    })
except Exception:
    pass

try:
    region_mean = df.groupby('region')['claim_amount'].mean().reset_index()
    region_mean = region_mean.sort_values('claim_amount', ascending=False)
    result['segments'].append({
        "segment_column": "region",
        "metric_column": "claim_amount",
        "aggregation": "mean",
        "label": None,
        "results": [{"name": str(row['region']), "value": float(row['claim_amount'])} for _, row in region_mean.iterrows()]
    })
except Exception:
    pass

try:
    total_claims = df['claim_amount'].sum()
    total_premium = df['earned_premium'].sum()
    overall_lr = total_claims / total_premium if total_premium > 0 else float('nan')
    region_lr = df.groupby('region').apply(
        lambda g: g['claim_amount'].sum() / g['earned_premium'].sum() if g['earned_premium'].sum() > 0 else float('nan')
    ).reset_index()
    region_lr.columns = ['region', 'loss_ratio']
    region_lr = region_lr.sort_values('loss_ratio', ascending=False)
    result['segments'].append({
        "segment_column": "region",
        "metric_column": "claim_amount",
        "aggregation": "ratio",
        "label": "loss_ratio",
        "results": [{"name": str(row['region']), "value": float(row['loss_ratio'])} for _, row in region_lr.iterrows()]
    })
except Exception:
    pass

try:
    region_count = df.groupby('region')['claim_amount'].count().reset_index()
    region_count = region_count.sort_values('claim_amount', ascending=False)
    result['segments'].append({
        "segment_column": "region",
        "metric_column": "claim_amount",
        "aggregation": "count",
        "label": None,
        "results": [{"name": str(row['region']), "value": float(row['claim_amount'])} for _, row in region_count.iterrows()]
    })
except Exception:
    pass

try:
    from scipy import stats as _stats
    groups = [grp['claim_amount'].values for _, grp in df.groupby('region')]
    if len(groups) >= 2:
        f_stat, p_val = _stats.f_oneway(*groups)
        result['statistical_tests'].append({
            "test_name": "One-way ANOVA: claim_amount by region",
            "statistic": float(f_stat),
            "p_value": float(p_val),
            "interpretation": f"F={f_stat:.3f}, p={p_val:.3g}; " + (
                "claim amounts differ significantly across regions." if p_val < 0.05
                else "no significant difference in claim amounts across regions."
            )
        })
except Exception:
    pass

try:
    result['assumptions'].append("Loss ratio computed as sum(claim_amount)/sum(earned_premium) per region over full dataset.")
    result['assumptions'].append("ANOVA assumes independence; rows are policy-months, not independent policies.")
    result['assumptions'].append("claim_amount includes zero-claim rows, which skews means downward.")
except Exception:
    pass

# ─── Guaranteed EDA + chart distributions + briefing (always runs) ───

try:
